                    .when(agentFactory).deployAgent(any(), anyString(), anyInt(), any());

            management.checkDeployments();

            verify(deploymentStore, never()).setDeploymentInfo(anyString(), anyString(), anyInt(),
                    eq(DeploymentInfo.DeploymentStatus.undeployed));
        }

